/* Mosswold Vale — interface chrome over a pixel-art world. */
:root {
  --ink: #163327;
  --ink-soft: #2b4c3b;
  --parchment: #f7e8bf;
  --parchment-dim: #cbbd96;
  --gold: #e9bd68;
  --gold-bright: #ffdb8b;
  --moss: #7fb877;
  --glass: rgba(17, 39, 30, 0.72);
  --glass-line: rgba(238, 218, 165, 0.24);
  --joystick-size: 132px;
  --knob-size: 54px;
  --joy-x: 0px;
  --joy-y: 0px;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #1b3a2b;
}

body {
  font-family: ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, "Courier New", monospace;
  color: var(--parchment);
  overscroll-behavior: none;
}

#app {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  background: #315c41;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  cursor: default;
}

/* ------------------------------------------------------------------ */
/* Atmosphere                                                          */
/* ------------------------------------------------------------------ */

.atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse 95% 70% at 24% 12%, rgba(255, 224, 158, 0.16), transparent 56%),
    radial-gradient(ellipse 80% 80% at 54% 48%, transparent 52%, rgba(8, 28, 22, 0.2) 100%),
    linear-gradient(180deg, rgba(255, 211, 138, 0.05), transparent 24%, transparent 76%, rgba(5, 19, 15, 0.26));
  mix-blend-mode: multiply;
}

.atmosphere::after {
  content: "";
  position: absolute;
  inset: 0;
  box-shadow:
    inset 0 0 80px rgba(7, 20, 15, 0.42),
    inset 0 0 180px rgba(7, 20, 15, 0.2);
}

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */

.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 5;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding:
    calc(16px + env(safe-area-inset-top))
    calc(18px + env(safe-area-inset-right))
    0
    calc(18px + env(safe-area-inset-left));
  pointer-events: none;
  animation: hud-in 1s 0.25s both cubic-bezier(0.2, 0.8, 0.2, 1);
}

.place-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 15px 9px 9px;
  border: 1px solid var(--glass-line);
  border-radius: 13px;
  background:
    linear-gradient(135deg, rgba(255, 241, 198, 0.06), transparent 58%),
    var(--glass);
  box-shadow:
    0 10px 30px rgba(7, 21, 16, 0.28),
    inset 0 1px rgba(255, 245, 207, 0.08);
  backdrop-filter: blur(9px) saturate(1.1);
  -webkit-backdrop-filter: blur(9px) saturate(1.1);
}

.rune {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(233, 189, 104, 0.38);
  border-radius: 9px;
  background:
    radial-gradient(circle at 38% 28%, rgba(255, 229, 158, 0.2), transparent 60%),
    rgba(10, 30, 23, 0.62);
  color: #8fd08a;
  box-shadow: inset 0 0 12px rgba(134, 208, 138, 0.1);
}

.rune svg {
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 1px 0 rgba(4, 14, 10, 0.6));
}

.place-text {
  min-width: 0;
}

.eyebrow {
  margin: 0;
  font-family: Georgia, "Palatino Linotype", "Book Antiqua", Palatino, serif;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.055em;
  line-height: 1.1;
  color: var(--parchment);
  text-shadow: 0 1px 0 rgba(5, 16, 12, 0.65);
  white-space: nowrap;
}

.subtitle {
  margin: 3px 0 0;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.18em;
  line-height: 1.2;
  text-transform: uppercase;
  color: rgba(224, 213, 176, 0.55);
  white-space: nowrap;
}

.found-card {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--glass-line);
  border-radius: 12px;
  background: var(--glass);
  box-shadow:
    0 10px 30px rgba(7, 21, 16, 0.25),
    inset 0 1px rgba(255, 245, 207, 0.07);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}

.found-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: rgba(228, 215, 177, 0.55);
}

.found-count {
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.03em;
  color: var(--gold-bright);
}

.found-total {
  margin-left: 2px;
  color: rgba(233, 218, 178, 0.42);
}

.found-gem {
  width: 7px;
  height: 7px;
  transform: rotate(45deg);
  background: var(--gold);
  box-shadow: 0 0 8px rgba(233, 189, 104, 0.5);
}

.found-card.is-complete {
  border-color: rgba(233, 189, 104, 0.48);
  box-shadow:
    0 0 26px rgba(233, 189, 104, 0.18),
    0 10px 30px rgba(7, 21, 16, 0.25);
}

/* ------------------------------------------------------------------ */
/* Chapter intro                                                       */
/* ------------------------------------------------------------------ */

.intro {
  position: absolute;
  z-index: 4;
  top: 17%;
  left: 50%;
  width: min(90vw, 620px);
  transform: translateX(-50%);
  text-align: center;
  pointer-events: none;
  animation: intro-cycle 7s 0.25s both cubic-bezier(0.2, 0.8, 0.2, 1);
  filter: drop-shadow(0 3px 0 rgba(4, 19, 13, 0.34));
}

.intro-kicker {
  margin: 0 0 10px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--gold);
  text-shadow: 0 1px 6px rgba(5, 17, 12, 0.7);
}

.intro h1 {
  margin: 0;
  font-family: Georgia, "Palatino Linotype", "Book Antiqua", Palatino, serif;
  font-size: clamp(36px, 7vw, 64px);
  font-weight: 700;
  letter-spacing: 0.035em;
  line-height: 1;
  color: #fff2c9;
  text-shadow:
    0 2px 0 rgba(94, 52, 27, 0.75),
    0 10px 34px rgba(5, 20, 14, 0.55);
}

.intro-sub {
  margin: 12px 0 0;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(246, 234, 199, 0.7);
  text-shadow: 0 1px 8px rgba(5, 17, 12, 0.8);
}

.intro-rule {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.intro-rule::before,
.intro-rule::after {
  content: "";
  width: 58px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(233, 189, 104, 0.65));
}

.intro-rule::after {
  background: linear-gradient(90deg, rgba(233, 189, 104, 0.65), transparent);
}

.intro-rule span {
  width: 5px;
  height: 5px;
  transform: rotate(45deg);
  background: var(--gold);
  box-shadow: 0 0 10px rgba(233, 189, 104, 0.5);
}

/* ------------------------------------------------------------------ */
/* Landmark toast                                                      */
/* ------------------------------------------------------------------ */

.toast {
  position: absolute;
  top: calc(88px + env(safe-area-inset-top));
  left: 50%;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 208px;
  padding: 10px 16px 10px 12px;
  border: 1px solid rgba(233, 189, 104, 0.3);
  border-radius: 12px;
  background:
    linear-gradient(120deg, rgba(233, 189, 104, 0.09), transparent 60%),
    rgba(15, 36, 27, 0.88);
  box-shadow:
    0 16px 40px rgba(4, 15, 11, 0.42),
    inset 0 1px rgba(255, 243, 202, 0.09);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -12px) scale(0.97);
  transition: opacity 0.45s ease, transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.toast-gem {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  border: 1px solid rgba(233, 189, 104, 0.5);
  border-radius: 6px;
  background:
    radial-gradient(circle at 50% 50%, rgba(255, 236, 174, 0.95) 0 2px, transparent 3px),
    linear-gradient(135deg, rgba(233, 189, 104, 0.24), rgba(104, 156, 103, 0.15));
  box-shadow: inset 0 0 10px rgba(233, 189, 104, 0.15);
}

.toast-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.toast-kicker {
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.21em;
  text-transform: uppercase;
  color: rgba(233, 189, 104, 0.8);
}

.toast strong {
  font-family: Georgia, "Palatino Linotype", "Book Antiqua", Palatino, serif;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.015em;
  color: var(--parchment);
}

/* ------------------------------------------------------------------ */
/* Controls                                                            */
/* ------------------------------------------------------------------ */

.controls {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
}

.joystick {
  position: absolute;
  left: calc(20px + env(safe-area-inset-left));
  bottom: calc(20px + env(safe-area-inset-bottom));
  width: var(--joystick-size);
  height: var(--joystick-size);
  pointer-events: auto;
  touch-action: none;
  opacity: 0.82;
  transition: opacity 0.3s ease;
}

.joystick:active,
.joystick.is-active {
  opacity: 1;
}

.joystick-halo {
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  background: radial-gradient(circle, transparent 56%, rgba(7, 25, 18, 0.2) 64%, transparent 74%);
  pointer-events: none;
}

.joystick-base {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid rgba(238, 218, 165, 0.28);
  background:
    radial-gradient(circle at 36% 28%, rgba(255, 241, 198, 0.09), transparent 38%),
    radial-gradient(circle, rgba(26, 51, 39, 0.36) 0 47%, rgba(13, 34, 26, 0.62) 100%);
  box-shadow:
    inset 0 0 24px rgba(4, 17, 12, 0.38),
    inset 0 1px rgba(255, 239, 193, 0.11),
    0 10px 30px rgba(4, 16, 11, 0.25);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  transition: transform 0.18s ease;
}

.joystick.is-active .joystick-base {
  transform: scale(0.985);
}

.joy-ring {
  position: absolute;
  inset: 14px;
  border: 1px dashed rgba(233, 189, 104, 0.2);
  border-radius: 50%;
  pointer-events: none;
}

.joy-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--knob-size);
  height: var(--knob-size);
  margin-left: calc(var(--knob-size) / -2);
  margin-top: calc(var(--knob-size) / -2);
  border: 1px solid rgba(255, 226, 153, 0.45);
  border-radius: 50%;
  background:
    radial-gradient(circle at 38% 30%, rgba(255, 244, 202, 0.34), transparent 45%),
    linear-gradient(150deg, rgba(93, 134, 91, 0.72), rgba(30, 62, 46, 0.92));
  box-shadow:
    0 6px 16px rgba(3, 14, 10, 0.45),
    inset 0 1px rgba(255, 247, 212, 0.2),
    inset 0 -5px 12px rgba(6, 21, 15, 0.32);
  transform: translate3d(var(--joy-x), var(--joy-y), 0);
  will-change: transform;
  pointer-events: none;
}

.joy-knob-glint {
  position: absolute;
  top: 16%;
  left: 28%;
  width: 30%;
  height: 18%;
  border-radius: 50%;
  background: rgba(255, 247, 211, 0.24);
  filter: blur(1px);
  transform: rotate(-20deg);
}

.joy-tick {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0.42;
  pointer-events: none;
}

.joy-tick-up {
  top: 7px;
  left: 50%;
  margin-left: -3px;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-bottom: 4px solid rgba(240, 220, 166, 0.8);
}

.joy-tick-right {
  right: 7px;
  top: 50%;
  margin-top: -3px;
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  border-left: 4px solid rgba(240, 220, 166, 0.8);
}

.joy-tick-down {
  bottom: 7px;
  left: 50%;
  margin-left: -3px;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-top: 4px solid rgba(240, 220, 166, 0.8);
}

.joy-tick-left {
  left: 7px;
  top: 50%;
  margin-top: -3px;
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  border-right: 4px solid rgba(240, 220, 166, 0.8);
}

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(26px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  padding: 7px 12px;
  border: 1px solid rgba(239, 222, 175, 0.14);
  border-radius: 20px;
  background: rgba(13, 33, 25, 0.45);
  box-shadow: 0 8px 24px rgba(4, 16, 11, 0.2);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
  color: rgba(238, 225, 189, 0.6);
  transition: opacity 1.1s 4s ease;
}

.hint i {
  font-style: normal;
  color: rgba(233, 189, 104, 0.65);
}

.touch-only {
  display: none;
}

/* tiny decorative brackets */
.corner {
  position: absolute;
  z-index: 4;
  width: 26px;
  height: 26px;
  pointer-events: none;
  opacity: 0.35;
  border-color: rgba(237, 214, 159, 0.55);
}

.corner-bl {
  left: calc(14px + env(safe-area-inset-left));
  bottom: calc(14px + env(safe-area-inset-bottom));
  border-left: 1px solid;
  border-bottom: 1px solid;
}

.corner-br {
  right: calc(14px + env(safe-area-inset-right));
  bottom: calc(14px + env(safe-area-inset-bottom));
  border-right: 1px solid;
  border-bottom: 1px solid;
}

.noscript {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #1b3a2b;
  color: var(--parchment);
  text-align: center;
}

/* ------------------------------------------------------------------ */
/* Motion                                                              */
/* ------------------------------------------------------------------ */

@keyframes hud-in {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes intro-cycle {
  0% {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  12% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  55% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -10px);
  }
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 720px), (pointer: coarse) {
  .desktop-only {
    display: none;
  }

  .touch-only {
    display: inline;
  }

  .hint {
    left: auto;
    right: calc(18px + env(safe-area-inset-right));
    bottom: calc(30px + env(safe-area-inset-bottom));
    transform: none;
    max-width: 44vw;
    white-space: normal;
    line-height: 1.45;
    text-align: right;
    background: rgba(13, 33, 25, 0.36);
    border-color: rgba(239, 222, 175, 0.1);
  }

  .corner {
    display: none;
  }

  .intro {
    top: 15.5%;
  }

  .intro h1 {
    font-size: clamp(31px, 10.5vw, 46px);
  }

  .toast {
    top: calc(80px + env(safe-area-inset-top));
    min-width: 0;
    max-width: calc(100vw - 40px);
  }

  .toast strong {
    font-size: 14px;
  }
}

@media (max-width: 430px) {
  :root {
    --joystick-size: 124px;
    --knob-size: 50px;
  }

  .hud {
    padding-left: calc(12px + env(safe-area-inset-left));
    padding-right: calc(12px + env(safe-area-inset-right));
    padding-top: calc(12px + env(safe-area-inset-top));
  }

  .place-card {
    padding: 7px 11px 7px 7px;
    gap: 8px;
  }

  .rune {
    width: 30px;
    height: 30px;
  }

  .rune svg {
    width: 19px;
    height: 19px;
  }

  .eyebrow {
    font-size: 13.5px;
  }

  .subtitle {
    font-size: 7.5px;
    letter-spacing: 0.13em;
  }

  .found-card {
    gap: 6px;
    padding: 7px 9px;
  }

  .found-label {
    display: none;
  }

  .found-count {
    font-size: 12px;
  }

  .hint {
    bottom: calc(28px + env(safe-area-inset-bottom));
    max-width: 38vw;
    font-size: 7px;
    letter-spacing: 0.11em;
  }

  .joystick {
    left: calc(16px + env(safe-area-inset-left));
    bottom: calc(18px + env(safe-area-inset-bottom));
  }
}

@media (max-height: 500px) {
  .intro {
    top: 10%;
  }

  .intro h1 {
    font-size: 34px;
  }

  .intro-sub,
  .intro-rule {
    display: none;
  }

  .toast {
    top: 68px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hud,
  .intro {
    animation-duration: 0.01s;
  }

  .intro {
    animation: none;
    opacity: 1;
  }

  .toast {
    transition-duration: 0.01s;
  }
}

/** Shared tuning values for Mosswold Vale. */
export const TILE = 16;
export const COLS = 48;
export const ROWS = 36;
export const WORLD_W = COLS * TILE;
export const WORLD_H = ROWS * TILE;

export const PLAYER = {
  walkSpeed: 60,
  acceleration: 12.5,
  radius: 5,
  startX: 24 * TILE,
  startY: 28 * TILE,
  animDistance: 9,
};

export const CAMERA = {
  follow: 7.5,
  lookAhead: 9,
  deadzone: 0.6,
};

export const COLORS = {
  outline: "#2b2634",
  grass: "#5da653",
  path: "#c9a76d",
  water: "#3d7f8f",
  gold: "#e9bd68",
  parchment: "#f7e8bf",
};

/** Landmarks are discovered by walking near them. */
export const LANDMARKS = [
  {
    id: "well",
    title: "The Old Well",
    x: 24 * TILE,
    y: 21.6 * TILE,
    radius: 46,
  },
  {
    id: "cottage",
    title: "Hearthstone Cottage",
    x: 11.5 * TILE,
    y: 13.2 * TILE,
    radius: 58,
  },
  {
    id: "inn",
    title: "The Wayfarer's Inn",
    x: 34 * TILE,
    y: 23.2 * TILE,
    radius: 64,
  },
  {
    id: "tower",
    title: "Starfall Tower",
    x: 39 * TILE,
    y: 12.5 * TILE,
    radius: 62,
  },
];

/** Small math, timing, and canvas helpers. */
export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const dist2 = (ax, ay, bx, by) => (ax - bx) ** 2 + (ay - by) ** 2;
export const TAU = Math.PI * 2;

/** Deterministic 32-bit PRNG so the village is the same every visit. */
export function mulberry32(seed) {
  let state = seed >>> 0;
  return function random() {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Stable hash for tile-scale variation. */
export function hash2(x, y, seed = 0) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export function createCanvas(width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(width));
  canvas.height = Math.max(1, Math.round(height));
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  return { canvas, ctx };
}

export function roundRectPath(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

/**
 * Procedural pixel art. Every tile and sprite is drawn once into a small
 * offscreen canvas, then blitted with nearest-neighbour scaling at runtime.
 */
import { createCanvas, mulberry32 } from "./util.js";

const C = {
  outline: "#2b2634",
  outlineDeep: "#1f2d26",
  grass: "#5aa552",
  grassDark: "#4b9248",
  grassLight: "#6db95d",
  grassHi: "#84c66b",
  grassDeep: "#3e7f40",
  path: "#c6a169",
  pathDark: "#ae8954",
  pathLight: "#d8b77c",
  pathHi: "#e6cc93",
  dirt: "#b7935f",
  dirtDark: "#9c7b4e",
  water: "#3b7d8d",
  waterDark: "#2f6978",
  waterLight: "#4f95a2",
  waterHi: "#74b1b6",
  sand: "#cbb37d",
  sandDark: "#b39964",
  bark: "#6b4a32",
  barkDark: "#4c3425",
  barkLight: "#835d3d",
  leaf: "#2f7047",
  leafMid: "#3c8b4f",
  leafLight: "#57aa5c",
  leafHi: "#7cc36a",
  stone: "#9b9c91",
  stoneDark: "#6f7269",
  stoneLight: "#b9b9a8",
  cream: "#ecdaae",
  creamDark: "#d5bf8e",
  timber: "#7b5134",
  timberDark: "#583722",
  roof: "#b75c47",
  roofDark: "#884034",
  roofLight: "#d27a5c",
  slate: "#58718a",
  slateDark: "#3d5268",
  slateLight: "#7890a4",
  glow: "#ffd889",
  glowSoft: "#f7c264",
  cloak: "#b04a3d",
  cloakDark: "#84362f",
  cloakLight: "#ce6450",
  skin: "#f2c79a",
  skinDark: "#d7a172",
  hair: "#7e4035",
  hairLight: "#a95c48",
  tunic: "#f1dfb6",
  tunicDark: "#d8c18f",
  leather: "#6b4631",
  gold: "#e9bd68",
};

const rect = (ctx, x, y, w, h, color) => {
  ctx.fillStyle = color;
  ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
};

const outlineRect = (ctx, x, y, w, h, fill, line = C.outline) => {
  rect(ctx, x - 1, y - 1, w + 2, h + 2, line);
  rect(ctx, x, y, w, h, fill);
};

function pixelEllipse(ctx, cx, cy, rx, ry, color) {
  ctx.fillStyle = color;
  for (let y = -ry; y <= ry; y++) {
    const span = Math.floor(rx * Math.sqrt(Math.max(0, 1 - (y * y) / (ry * ry))));
    ctx.fillRect(Math.round(cx - span), Math.round(cy + y), Math.max(1, span * 2 + 1), 1);
  }
}

function pixelCircle(ctx, cx, cy, r, color) {
  pixelEllipse(ctx, cx, cy, r, r, color);
}

/* ------------------------------------------------------------------ */
/* Ground tiles                                                        */
/* ------------------------------------------------------------------ */

function grassTile(rng) {
  const { canvas, ctx } = createCanvas(16, 16);
  rect(ctx, 0, 0, 16, 16, C.grass);
  const patches = 9 + Math.floor(rng() * 5);
  for (let i = 0; i < patches; i++) {
    const x = Math.floor(rng() * 15);
    const y = Math.floor(rng() * 15);
    const w = 1 + Math.floor(rng() * 3);
    const h = 1 + Math.floor(rng() * 2);
    const tone = rng();
    rect(ctx, x, y, w, h, tone < 0.34 ? C.grassDark : tone < 0.7 ? C.grassLight : C.grassHi);
  }
  for (let i = 0; i < 4; i++) {
    const x = 1 + Math.floor(rng() * 13);
    const y = 3 + Math.floor(rng() * 11);
    rect(ctx, x, y, 1, 2, C.grassDeep);
    rect(ctx, x + 1, y - 1, 1, 1, C.grassHi);
  }
  return canvas;
}

function pathTile(rng) {
  const { canvas, ctx } = createCanvas(16, 16);
  rect(ctx, 0, 0, 16, 16, C.path);
  for (let i = 0; i < 17; i++) {
    const x = Math.floor(rng() * 15);
    const y = Math.floor(rng() * 15);
    const w = 1 + Math.floor(rng() * 3);
    const h = 1 + Math.floor(rng() * 2);
    const tone = rng();
    rect(ctx, x, y, w, h, tone < 0.36 ? C.pathDark : tone < 0.72 ? C.pathLight : C.pathHi);
  }
  for (let i = 0; i < 3; i++) {
    const x = 2 + Math.floor(rng() * 11);
    const y = 2 + Math.floor(rng() * 11);
    rect(ctx, x, y, 2, 1, rng() > 0.5 ? "#9c7c4e" : "#e8cf9a");
  }
  return canvas;
}

function dirtTile(rng) {
  const { canvas, ctx } = createCanvas(16, 16);
  rect(ctx, 0, 0, 16, 16, C.dirt);
  for (let i = 0; i < 14; i++) {
    const x = Math.floor(rng() * 15);
    const y = Math.floor(rng() * 15);
    rect(ctx, x, y, 1 + Math.floor(rng() * 3), 1, rng() > 0.5 ? C.dirtDark : C.pathLight);
  }
  for (let i = 0; i < 2; i++) {
    const x = 3 + Math.floor(rng() * 10);
    const y = 3 + Math.floor(rng() * 10);
    rect(ctx, x, y, 2, 1, "#87693f");
    rect(ctx, x + 1, y - 1, 1, 1, C.pathHi);
  }
  return canvas;
}

function sandTile(rng) {
  const { canvas, ctx } = createCanvas(16, 16);
  rect(ctx, 0, 0, 16, 16, C.sand);
  for (let i = 0; i < 13; i++) {
    rect(
      ctx,
      Math.floor(rng() * 15),
      Math.floor(rng() * 15),
      1 + Math.floor(rng() * 2),
      1,
      rng() > 0.48 ? C.sandDark : "#dac58f"
    );
  }
  return canvas;
}

function waterTile(rng) {
  const { canvas, ctx } = createCanvas(16, 16);
  rect(ctx, 0, 0, 16, 16, C.water);
  for (let i = 0; i < 10; i++) {
    rect(
      ctx,
      Math.floor(rng() * 14),
      Math.floor(rng() * 15),
      2 + Math.floor(rng() * 4),
      1,
      rng() > 0.46 ? C.waterDark : C.waterLight
    );
  }
  for (let i = 0; i < 3; i++) {
    const x = Math.floor(rng() * 11);
    const y = 2 + Math.floor(rng() * 12);
    rect(ctx, x, y, 3, 1, "rgba(190, 232, 226, 0.32)");
  }
  return canvas;
}

export function makeTiles(rngSeed = 11) {
  const rng = mulberry32(rngSeed);
  const make = (fn, count = 5) => Array.from({ length: count }, () => fn(rng));
  return {
    grass: make(grassTile, 6),
    path: make(pathTile, 5),
    dirt: make(dirtTile, 5),
    sand: make(sandTile, 4),
    water: make(waterTile, 4),
  };
}

/* ------------------------------------------------------------------ */
/* Nature                                                              */
/* ------------------------------------------------------------------ */

const canopyBlobs = [
  [23, 20, 13],
  [12, 25, 9],
  [34, 25, 10],
  [18, 32, 9],
  [29, 32, 8],
  [23, 11, 9],
  [31, 16, 8],
  [14, 17, 8],
];

export function makeTree(variant = 0) {
  const rng = mulberry32(300 + variant * 97);
  const { canvas, ctx } = createCanvas(48, 58);
  const ax = 24;
  const ay = 54;

  // Soft ground shadow.
  ctx.globalAlpha = 0.24;
  pixelEllipse(ctx, 24, 52, 18, 4, "#173a29");
  ctx.globalAlpha = 1;

  // Trunk and roots.
  outlineRect(ctx, 20, 34, 8, 18, C.bark, C.barkDark);
  rect(ctx, 21, 36, 2, 14, C.barkLight);
  rect(ctx, 18, 50, 5, 3, C.bark, C.barkDark);
  rect(ctx, 26, 50, 5, 3, C.bark, C.barkDark);
  rect(ctx, 17, 48, 3, 2, C.barkLight);
  rect(ctx, 29, 48, 3, 2, C.barkLight);
  rect(ctx, 22, 31, 2, 6, C.barkDark);
  rect(ctx, 27, 28, 2, 7, C.barkDark);

  const shiftX = variant === 1 ? -1 : variant === 2 ? 1 : 0;
  const shiftY = variant === 2 ? -1 : 0;

  // Dark silhouette gives the canopy a crisp, hand-drawn rim.
  for (const [bx, by, br] of canopyBlobs) {
    pixelCircle(ctx, bx + shiftX, by + shiftY + 1, br + 2, "#2a5e3d");
  }
  for (const [bx, by, br] of canopyBlobs) {
    pixelCircle(ctx, bx + shiftX, by + shiftY, br, C.leaf);
  }

  // Mid-tone clumps, offset up-left toward the morning sun.
  for (const [bx, by, br] of canopyBlobs) {
    pixelCircle(ctx, bx + shiftX - 1, by + shiftY - 2, Math.max(4, br - 3), C.leafMid);
  }
  for (const [bx, by, br] of [
    [18, 18, 8],
    [28, 17, 7],
    [13, 24, 6],
    [23, 26, 8],
    [33, 25, 6],
    [19, 31, 5],
  ]) {
    pixelCircle(ctx, bx + shiftX, by + shiftY, br, C.leafLight);
  }

  // Leafy speckles and sunlit edges.
  for (let i = 0; i < 34; i++) {
    const blob = canopyBlobs[Math.floor(rng() * canopyBlobs.length)];
    const angle = rng() * Math.PI * 2;
    const radius = Math.sqrt(rng()) * (blob[2] - 2);
    const x = Math.round(blob[0] + shiftX + Math.cos(angle) * radius);
    const y = Math.round(blob[1] + shiftY + Math.sin(angle) * radius);
    const tone = rng();
    rect(ctx, x, y, tone > 0.8 ? 2 : 1, 1, tone > 0.58 ? C.leafHi : tone > 0.25 ? C.leafMid : "#25603e");
  }
  for (let i = 0; i < 9; i++) {
    const x = 9 + Math.floor(rng() * 29) + shiftX;
    const y = 9 + Math.floor(rng() * 20) + shiftY;
    rect(ctx, x, y, 1, 1, C.leafHi);
  }

  // A hint of warm light on the crown.
  rect(ctx, 20 + shiftX, 6 + shiftY, 5, 1, "#95d17a");
  rect(ctx, 17 + shiftX, 8 + shiftY, 3, 1, "#88ca72");

  return { canvas, ax, ay };
}

export function makeBush(variant = 0) {
  const rng = mulberry32(800 + variant * 41);
  const { canvas, ctx } = createCanvas(30, 28);
  ctx.globalAlpha = 0.2;
  pixelEllipse(ctx, 15, 24, 11, 3, "#173a29");
  ctx.globalAlpha = 1;
  const blobs = [
    [9, 16, 7],
    [20, 16, 7],
    [14, 11, 8],
    [23, 20, 4],
  ];
  for (const [x, y, r] of blobs) pixelCircle(ctx, x, y + 1, r + 1, "#2a5e3d");
  for (const [x, y, r] of blobs) pixelCircle(ctx, x, y, r, C.leafMid);
  for (const [x, y, r] of blobs) pixelCircle(ctx, x - 1, y - 2, Math.max(2, r - 3), C.leafLight);
  for (let i = 0; i < 12; i++) {
    rect(ctx, 4 + Math.floor(rng() * 22), 7 + Math.floor(rng() * 15), 1, 1, rng() > 0.5 ? C.leafHi : "#25603e");
  }
  if (variant === 1) {
    rect(ctx, 8, 14, 2, 2, "#e9bd68");
    rect(ctx, 19, 10, 2, 2, "#e9bd68");
  }
  return { canvas, ax: 15, ay: 25 };
}

export function makeRock(variant = 0) {
  const rng = mulberry32(1200 + variant * 33);
  const { canvas, ctx } = createCanvas(28, 22);
  ctx.globalAlpha = 0.2;
  pixelEllipse(ctx, 14, 19, 11, 2, "#173a29");
  ctx.globalAlpha = 1;
  const rows = variant === 1 ? [4, 7, 9, 10, 10, 9, 7] : [3, 6, 8, 10, 10, 8, 5];
  const baseY = 18 - rows.length;
  for (let i = 0; i < rows.length; i++) {
    const w = rows[i];
    const x = 14 - w;
    rect(ctx, x - 1, baseY + i, w * 2 + 2, 1, "#555a52");
    rect(ctx, x, baseY + i, w * 2, 1, C.stone);
  }
  for (let i = 0; i < 4; i++) {
    const w = Math.max(2, rows[i] - 2);
    rect(ctx, 14 - w - 1, baseY + i + 1, Math.floor(w * 0.8), 1, C.stoneLight);
  }
  rect(ctx, 8, 15, 5, 2, C.stoneDark);
  for (let i = 0; i < 6; i++) {
    rect(ctx, 7 + Math.floor(rng() * 14), baseY + 2 + Math.floor(rng() * 4), 1, 1, "#c6c5b4");
  }
  // Moss on the sunless edge.
  rect(ctx, 18, 17, 4, 1, "#5e8c4d");
  rect(ctx, 10, 13, 2, 1, "#6b9a55");
  return { canvas, ax: 14, ay: 19 };
}

export function makeStump() {
  const { canvas, ctx } = createCanvas(20, 18);
  ctx.globalAlpha = 0.2;
  pixelEllipse(ctx, 10, 16, 7, 2, "#173a29");
  ctx.globalAlpha = 1;
  outlineRect(ctx, 5, 7, 10, 8, C.bark, C.barkDark);
  rect(ctx, 6, 4, 8, 4, C.bark, C.barkDark);
  pixelEllipse(ctx, 10, 4, 5, 2, C.barkLight);
  pixelEllipse(ctx, 10, 4, 3, 1, "#8d6240");
  rect(ctx, 11, 4, 1, 1, "#5b3b28");
  rect(ctx, 7, 6, 1, 2, "#a77a4e");
  return { canvas, ax: 10, ay: 15 };
}

