function segmentDistance(px, py, ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  const lengthSq = dx * dx + dy * dy || 1;
  const t = clamp(((px - ax) * dx + (py - ay) * dy) / lengthSq, 0, 1);
  return Math.hypot(px - (ax + dx * t), py - (ay + dy * t));
}

function pointHitsRect(px, py, rect, pad = 0) {
  return px >= rect.x - pad && px <= rect.x + rect.w + pad && py >= rect.y - pad && py <= rect.y + rect.h + pad;
}

function drawFlower(ctx, x, y, palette) {
  ctx.fillStyle = "#3f7f42";
  ctx.fillRect(x, y - 3, 1, 4);
  ctx.fillRect(x - 1, y - 1, 1, 1);
  const petals = palette || ["#f2d16f", "#e98286", "#e7e4d0", "#b58de0"];
  const color = petals[Math.floor(hash2(x, y, 31) * petals.length)];
  ctx.fillStyle = color;
  ctx.fillRect(x - 1, y - 5, 1, 2);
  ctx.fillRect(x + 1, y - 5, 1, 2);
  ctx.fillRect(x, y - 6, 1, 1);
  ctx.fillRect(x, y - 4, 1, 1);
  ctx.fillStyle = "#f8dd8d";
  ctx.fillRect(x, y - 5, 1, 1);
}

function drawTuft(ctx, x, y) {
  ctx.fillStyle = "#3d7d40";
  ctx.fillRect(x, y - 3, 1, 4);
  ctx.fillRect(x - 2, y - 2, 1, 3);
  ctx.fillRect(x + 2, y - 1, 1, 2);
  ctx.fillStyle = "#79bd63";
  ctx.fillRect(x - 1, y - 4, 1, 3);
  ctx.fillRect(x + 1, y - 3, 1, 2);
}

function drawClover(ctx, x, y) {
  ctx.fillStyle = "#4b9148";
  ctx.fillRect(x, y - 1, 1, 2);
  ctx.fillStyle = "#6fb75f";
  ctx.fillRect(x - 1, y - 3, 2, 2);
  ctx.fillRect(x + 1, y - 2, 2, 2);
}

function drawMushroom(ctx, x, y, red = true) {
  ctx.fillStyle = "#e4d4ae";
  ctx.fillRect(x, y - 2, 1, 3);
  ctx.fillStyle = red ? "#c15449" : "#b58c5c";
  ctx.fillRect(x - 2, y - 4, 5, 2);
  ctx.fillRect(x - 1, y - 5, 3, 1);
  ctx.fillStyle = "#f3e8cb";
  ctx.fillRect(x - 1, y - 4, 1, 1);
  ctx.fillRect(x + 1, y - 3, 1, 1);
}

export class World {
  constructor() {
    this.tiles = makeTiles(29);
    this.terrain = Array.from({ length: ROWS }, () => Array(COLS).fill(GRASS));
    this.props = [];
    this.solidRects = [];
    this.solidCircles = [];
    this.waterTiles = [];
    this.smokeSources = [];
    this.landmarks = LANDMARKS.map((landmark) => ({ ...landmark, found: false }));
    this.spawn = { x: 24 * TILE, y: 28.4 * TILE };

    this.paintTerrain();
    this.placeBuildings();
    this.placeFences();
    this.placeTrees();
    this.placeScenery();
    this.placeLilies();
    this.addWaterCollision();
    this.ground = this.bakeGround();
  }

  /* ---------------------------------------------------------------- */
  /* Terrain                                                           */
  /* ---------------------------------------------------------------- */

  paintTerrain() {
    // The pond first: shore ring, then the dark water.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const nx = (x + 0.5 - 39.5) / 4.7;
        const ny = (y + 0.5 - 29.2) / 3.5;
        const d = nx * nx + ny * ny;
        if (d < 0.82) this.terrain[y][x] = WATER;
        else if (d < 1.18) this.terrain[y][x] = SAND;
      }
    }

    // Winding village roads, with a soft organic edge.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const px = x + 0.5;
        const py = y + 0.5;
        let distance = Infinity;
        for (const road of ROADS) {
          let best = Infinity;
          for (let i = 0; i < road.points.length - 1; i++) {
            const [ax, ay] = road.points[i];
            const [bx, by] = road.points[i + 1];
            best = Math.min(best, segmentDistance(px, py, ax, ay, bx, by) / road.width);
          }
          distance = Math.min(distance, best);
        }
        const wobble = (hash2(x, y, 7) - 0.5) * 0.32;
        if (distance < 1 + wobble) {
          this.terrain[y][x] = PATH;
        }
      }
    }

    // The green in the middle of the village becomes packed earth.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const nx = (x + 0.5 - 24) / 4.5;
        const ny = (y + 0.5 - 21) / 3.5;
        const d = nx * nx + ny * ny;
        const wobble = (hash2(x, y, 13) - 0.5) * 0.22;
        if (d < 1 + wobble) this.terrain[y][x] = DIRT;
      }
    }
  }

  terrainAtTile(x, y) {
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return WATER;
    return this.terrain[y][x];
  }

  terrainAtWorld(x, y) {
    return this.terrainAtTile(Math.floor(x / TILE), Math.floor(y / TILE));
  }

  /* ---------------------------------------------------------------- */
  /* Buildings and props                                               */
  /* ---------------------------------------------------------------- */

  addProp(prop) {
    this.props.push(prop);
    return prop;
  }

  addBuilding({ id, x, y, w, h, sprite, inset = 5 }) {
    const centerX = (x + w / 2) * TILE;
    const bottom = (y + h) * TILE;
    const prop = this.addProp({
      kind: "building",
      id,
      sprite,
      x: centerX,
      y: bottom + 5,
      sortY: bottom + 4,
    });
    this.solidRects.push({
      x: x * TILE + inset,
      y: y * TILE + 9,
      w: w * TILE - inset * 2,
      h: h * TILE - 9,
    });

    // Clear a little apron in front of each door so the village breathes.
    const clearX0 = Math.max(0, Math.floor(x) - 1);
    const clearX1 = Math.min(COLS - 1, Math.floor(x + w) + 1);
    const clearY0 = Math.max(0, Math.floor(y) - 1);
    const clearY1 = Math.min(ROWS - 1, Math.floor(y + h) + 1);
    for (let ty = clearY0; ty <= clearY1; ty++) {
      for (let tx = clearX0; tx <= clearX1; tx++) {
        if (this.terrain[ty][tx] === WATER) continue;
        if (tx >= x && tx < x + w && ty >= y && ty < y + h) this.terrain[ty][tx] = GRASS;
      }
    }
    return prop;
  }

  placeBuildings() {
    this.cottage = this.addBuilding({
      id: "cottage",
      x: 9,
      y: 9,
      w: 5,
      h: 4,
      sprite: makeCottage(),
    });
    this.inn = this.addBuilding({
      id: "inn",
      x: 33,
      y: 19,
      w: 6,
      h: 4,
      sprite: makeInn(),
    });
    this.tower = this.addBuilding({
      id: "tower",
      x: 38,
      y: 7,
      w: 4,
      h: 4,
      sprite: makeTower(),
    });

    // Chimney locations, used by the drifting smoke particles.
    this.smokeSources.push({
      x: this.cottage.x - this.cottage.sprite.ax + 78,
      y: this.cottage.y - this.cottage.sprite.ay + 4,
    });
    this.smokeSources.push({
      x: this.inn.x - this.inn.sprite.ax + 106,
      y: this.inn.y - this.inn.sprite.ay + 0,
    });

    // The well sits at the heart of the green.
    const well = this.addProp({
      kind: "well",
      sprite: makeWell(),
      x: 24 * TILE,
      y: 22 * TILE + 2,
      sortY: 22 * TILE,
    });
    this.solidCircles.push({ x: well.x, y: well.y - 7, r: 13 });

    // A signpost by the south road.
    this.addProp({
      kind: "sign",
      sprite: makeSignpost(),
      x: 27 * TILE + 4,
      y: 28.2 * TILE,
      sortY: 28.2 * TILE,
    });
    this.solidCircles.push({ x: 27 * TILE + 4, y: 28 * TILE, r: 4 });

    // Lanterns line the evening walk.
    for (const [x, y] of [
      [25.5, 25],
      [20.3, 20.3],
      [29.4, 20.9],
      [37, 17.4],
      [32.6, 14],
    ]) {
      this.addProp({
        kind: "lantern",
        sprite: makeLantern(),
        x: x * TILE,
        y: y * TILE,
        sortY: y * TILE,
      });
    }
  }

  placeFences() {
    const fenceH = makeFence(false);
    const fenceV = makeFence(true);
    const x0 = 4.6;
    const x1 = 9.4;
    const y0 = 15.4;
    const y1 = 20.4;
    const step = 1.05;
    const gateY = 18;

    const addFence = (x, y, vertical, solid = true) => {
      const prop = this.addProp({
        kind: "fence",
        sprite: vertical ? fenceV : fenceH,
        x: x * TILE,
        y: y * TILE,
        sortY: y * TILE,
      });
      if (solid) {
        this.solidRects.push({
          x: prop.x - (vertical ? 3 : 8),
          y: prop.y - (vertical ? 4 : 7),
          w: vertical ? 6 : 16,
          h: vertical ? 16 : 6,
        });
      }
    };

    for (let x = x0; x <= x1; x += step) {
      addFence(x, y0, false);
      addFence(x, y1, false);
    }
    for (let y = y0 + 1.1; y < y1; y += step) {
      addFence(x0, y, true);
      if (Math.abs(y - gateY) > 0.9) addFence(x1, y, true);
    }
  }

  placeTrees() {
    const rng = mulberry32(4172);
    const trees = [];
    const buildingRects = this.solidRects.filter((rect) => rect.w > 40 || rect.h > 40);

    const isClear = (x, y) => {
      const terrain = this.terrainAtWorld(x, y);
      if (terrain !== GRASS) return false;
      if (Math.hypot(x - this.spawn.x, y - this.spawn.y) < 74) return false;
      if (Math.hypot(x - 24 * TILE, y - 21 * TILE) < 74) return false;
      if (x < 5 * TILE && y > 14 * TILE && y < 21 * TILE) return false; // garden
      for (const rect of buildingRects) {
        if (pointHitsRect(x, y, rect, 19)) return false;
      }
      for (const tree of trees) {
        if (Math.hypot(x - tree.x, y - tree.y) < 20) return false;
      }
      return true;
    };

    const placeTree = (x, y) => {
      if (!isClear(x, y)) return false;
      const variant = Math.floor(rng() * 3);
      const sprite = makeTree(variant);
      const tree = this.addProp({
        kind: "tree",
        sprite,
        x: Math.round(x),
        y: Math.round(y),
        sortY: Math.round(y),
        variant,
      });
      this.solidCircles.push({ x: tree.x, y: tree.y - 5, r: 5.5 });
      trees.push(tree);
      return true;
    };

    // Scenic groves, including a dense forest frame around the village.
    const groves = [
      [4, 4, 78, 12],
      [12, 3, 65, 9],
      [27, 3, 74, 11],
      [43, 6, 66, 10],
      [44, 20, 62, 10],
      [43, 31, 70, 11],
      [28, 33.5, 70, 10],
      [14, 33, 74, 11],
      [3, 31, 64, 10],
      [3, 21, 56, 7],
      [18, 6, 44, 5],
      [32, 7, 42, 4],
      [12, 25, 40, 4],
      [18, 30, 36, 4],
    ];

    for (const [tx, ty, radius, count] of groves) {
      for (let i = 0; i < count * 3; i++) {
        if (count <= 0) break;
        const angle = rng() * Math.PI * 2;
        const distance = Math.sqrt(rng()) * radius;
        const x = tx * TILE + Math.cos(angle) * distance;
        const y = ty * TILE + Math.sin(angle) * distance;
        if (placeTree(x, y)) count--;
      }
    }

    // A few solitary characters in the meadow.
    for (let i = 0; i < 120; i++) {
      const x = 30 + rng() * (WORLD_W - 60);
      const y = 30 + rng() * (WORLD_H - 60);
      if (rng() > 0.68) placeTree(x, y);
    }

    // Reinforce the outermost frame so the world feels held in a wood.
    for (let ty = 0; ty < ROWS; ty++) {
      for (let tx = 0; tx < COLS; tx++) {
        const edge = Math.min(tx, ty, COLS - 1 - tx, ROWS - 1 - ty);
        if (edge > 1) continue;
        if (hash2(tx, ty, 51) > 0.46) {
          placeTree(tx * TILE + 8 + (rng() - 0.5) * 8, ty * TILE + 10 + (rng() - 0.5) * 6);
        }
      }
    }
  }

  placeScenery() {
    const rng = mulberry32(991);

    const canPlace = (x, y, pad = 14) => {
      if (this.terrainAtWorld(x, y) !== GRASS) return false;
      if (Math.hypot(x - this.spawn.x, y - this.spawn.y) < 46) return false;
      if (x < 5 * TILE && y > 14 * TILE && y < 21 * TILE) return false;
      for (const circle of this.solidCircles) {
        if (Math.hypot(x - circle.x, y - circle.y) < circle.r + pad) return false;
      }
      for (const rect of this.solidRects) {
        if (pointHitsRect(x, y, rect, pad)) return false;
      }
      return true;
    };

    // Rocks, mostly skirting the pond and the roads.
    const rockSpots = [
      [34.5, 27.3],
      [35.6, 26],
      [34, 32.3],
      [32.8, 30.8],
      [19.2, 23.2],
      [16.4, 13.9],
      [6.8, 12.2],
      [28.9, 11.6],
      [42.8, 16.4],
      [11.8, 27.7],
    ];
    let variant = 0;
    for (const [tx, ty] of rockSpots) {
      const x = tx * TILE;
      const y = ty * TILE;
      if (this.terrainAtWorld(x, y) === WATER) continue;
      const rock = this.addProp({
        kind: "rock",
        sprite: makeRock(variant++ % 2),
        x,
        y,
        sortY: y,
      });
      this.solidCircles.push({ x, y: y - 4, r: 6 });
    }
    for (let i = 0; i < 180; i++) {
      const x = 24 + rng() * (WORLD_W - 48);
      const y = 24 + rng() * (WORLD_H - 48);
      if (rng() > 0.72 && canPlace(x, y, 13)) {
        const rock = this.addProp({
          kind: "rock",
          sprite: makeRock(Math.floor(rng() * 2)),
          x,
          y,
          sortY: y,
        });
        this.solidCircles.push({ x, y: y - 4, r: 6 });
      }
    }

    // Bushes and stumps soften the tree line.
    for (let i = 0; i < 150; i++) {
      const x = 24 + rng() * (WORLD_W - 48);
      const y = 24 + rng() * (WORLD_H - 48);
      if (rng() > 0.78 && canPlace(x, y, 11)) {
        this.addProp({
          kind: "bush",
          sprite: makeBush(Math.floor(rng() * 2)),
          x,
          y,
          sortY: y,
        });
      }
    }
    for (const [tx, ty] of [
      [7.2, 8.2],
      [30.2, 8.4],
      [41.2, 25.4],
      [14.6, 22.4],
    ]) {
      const x = tx * TILE;
      const y = ty * TILE;
      const stump = this.addProp({
        kind: "stump",
        sprite: makeStump(),
        x,
        y,
        sortY: y,
      });
      this.solidCircles.push({ x, y: y - 3, r: 5 });
    }
  }

  placeLilies() {
    const rng = mulberry32(732);
    const water = [];
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (this.terrain[y][x] === WATER) water.push({ x, y });
      }
    }
    for (let i = 0; i < 9 && water.length; i++) {
      const tile = water[Math.floor(rng() * water.length)];
      this.addProp({
        kind: "lily",
        sprite: makeLily(),
        x: tile.x * TILE + 4 + rng() * 8,
        y: tile.y * TILE + 4 + rng() * 8,
        sortY: tile.y * TILE + 14,
      });
    }
  }

  addWaterCollision() {
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (this.terrain[y][x] === WATER) {
          this.waterTiles.push({ x, y });
          this.solidRects.push({
            x: x * TILE,
            y: y * TILE,
            w: TILE,
            h: TILE,
            water: true,
          });
        }
      }
    }
  }

  /* ---------------------------------------------------------------- */
  /* Ground bake                                                       */
  /* ---------------------------------------------------------------- */

  bakeGround() {
    const { canvas, ctx } = createCanvas(WORLD_W, WORLD_H);
    const rng = mulberry32(2048);

    // Base terrain tiles.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const type = this.terrain[y][x];
        const set =
          type === WATER
            ? this.tiles.water
            : type === SAND
              ? this.tiles.sand
              : type === PATH
                ? this.tiles.path
                : type === DIRT
                  ? this.tiles.dirt
                  : this.tiles.grass;
        const index = Math.floor(hash2(x, y, 3) * set.length);
        ctx.drawImage(set[index], x * TILE, y * TILE);
      }
    }

    // Blend road edges into the grass with sparse blades and crumbs.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const type = this.terrain[y][x];
        if (type !== PATH && type !== DIRT) continue;
        const wx = x * TILE;
        const wy = y * TILE;
        const neighbours = [
          [0, -1, 0, 0, TILE],
          [1, 0, TILE - 1, 0, TILE],
          [0, 1, 0, TILE - 1, TILE],
          [-1, 0, 0, 0, TILE],
        ];
        for (const [dx, dy, ex, ey] of neighbours) {
          if (this.terrainAtTile(x + dx, y + dy) !== GRASS) continue;
          for (let i = 0; i < TILE; i += 1) {
            if (hash2(wx + i, wy + i, 71) > 0.44) {
              const h = hash2(wx + i, wy, 72);
              if (dx === 0) {
                ctx.fillStyle = h > 0.55 ? "#4b8e45" : "#6bb35e";
                ctx.fillRect(wx + i, wy + ey + (dy < 0 ? 0 : -1), 1, 2);
              } else {
                ctx.fillStyle = h > 0.55 ? "#4b8e45" : "#6bb35e";
                ctx.fillRect(wx + ex + (dx < 0 ? 0 : -1), wy + i, 2, 1);
              }
            }
            if (hash2(wx + i, wy, 73) > 0.88) {
              if (dx === 0) {
                ctx.fillStyle = "#a88552";
                ctx.fillRect(wx + i, wy + (dy < 0 ? -1 : TILE), 1, 1);
              } else {
                ctx.fillStyle = "#a88552";
                ctx.fillRect(wx + (dx < 0 ? -1 : TILE), wy + i, 1, 1);
              }
            }
          }
        }
      }
    }

    // Pond rim: dark water line, pale foam, and damp sand.
    for (const tile of this.waterTiles) {
      const wx = tile.x * TILE;
      const wy = tile.y * TILE;
      for (const [dx, dy] of [
        [0, -1],
        [1, 0],
        [0, 1],
        [-1, 0],
      ]) {
        if (this.terrainAtTile(tile.x + dx, tile.y + dy) === WATER) continue;
        if (dy === -1) {
          ctx.fillStyle = "#2b6270";
          ctx.fillRect(wx, wy, TILE, 2);
          ctx.fillStyle = "#78b1b2";
          for (let i = 0; i < TILE; i += 3) ctx.fillRect(wx + i, wy + 2, 1, 1);
        } else if (dy === 1) {
          ctx.fillStyle = "#2b6270";
          ctx.fillRect(wx, wy + TILE - 2, TILE, 2);
          ctx.fillStyle = "#78b1b2";
          for (let i = 1; i < TILE; i += 4) ctx.fillRect(wx + i, wy + TILE - 3, 1, 1);
        } else if (dx === -1) {
          ctx.fillStyle = "#2b6270";
          ctx.fillRect(wx, wy, 2, TILE);
        } else {
          ctx.fillStyle = "#2b6270";
          ctx.fillRect(wx + TILE - 2, wy, 2, TILE);
        }
      }
    }

    // Ground decoration: flowers, clover, tufts, pebbles.
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (this.terrain[y][x] !== GRASS) continue;
        const wx = x * TILE;
        const wy = y * TILE;
        const nearGarden = x >= 5 && x <= 9 && y >= 16 && y <= 20;
        if (nearGarden) continue;

        const tuftRoll = hash2(x, y, 81);
        if (tuftRoll > 0.58) {
          drawTuft(ctx, wx + 3 + Math.floor(hash2(x, y, 82) * 11), wy + 6 + Math.floor(hash2(x, y, 83) * 9));
        }
        if (tuftRoll > 0.88) {
          drawTuft(ctx, wx + 3 + Math.floor(hash2(x, y, 84) * 10), wy + 4 + Math.floor(hash2(x, y, 85) * 9));
        }
        if (hash2(x, y, 86) > 0.87) {
          drawClover(ctx, wx + 4 + Math.floor(hash2(x, y, 87) * 9), wy + 5 + Math.floor(hash2(x, y, 88) * 8));
        }
        if (hash2(x, y, 89) > 0.915) {
          drawFlower(
            ctx,
            wx + 4 + Math.floor(hash2(x, y, 90) * 9),
            wy + 5 + Math.floor(hash2(x, y, 91) * 8)
          );
        }
        if (hash2(x, y, 92) > 0.55 && hash2(x, y, 93) > 0.8) {
          ctx.fillStyle = "#8b8c7c";
          ctx.fillRect(wx + 3 + Math.floor(hash2(x, y, 94) * 10), wy + 4 + Math.floor(hash2(x, y, 95) * 9), 1, 1);
        }
      }
    }

    // Wildflower drifts by the cottage and around the well.
    for (let i = 0; i < 90; i++) {
      const angle = rng() * Math.PI * 2;
      const radius = 15 + rng() * 70;
      const cx = 11.5 * TILE;
      const cy = 14.2 * TILE;
      const x = cx + Math.cos(angle) * radius;
      const y = cy + Math.sin(angle) * radius;
      if (this.terrainAtWorld(x, y) === GRASS) drawFlower(ctx, Math.round(x), Math.round(y));
    }
    for (let i = 0; i < 38; i++) {
      const angle = rng() * Math.PI * 2;
      const radius = 28 + rng() * 48;
      const x = 24 * TILE + Math.cos(angle) * radius;
      const y = 21.3 * TILE + Math.sin(angle) * radius * 0.7;
      if (this.terrainAtWorld(x, y) === GRASS) drawFlower(ctx, Math.round(x), Math.round(y));
    }

    // Mushrooms and leaf litter beneath the trees.
    for (const prop of this.props) {
      if (prop.kind !== "tree") continue;
      const roll = hash2(prop.x, prop.y, 101);
      if (roll > 0.62) {
        const ox = (hash2(prop.x, prop.y, 102) - 0.5) * 24;
        const oy = 3 + hash2(prop.x, prop.y, 103) * 7;
        drawMushroom(ctx, Math.round(prop.x + ox), Math.round(prop.y + oy), roll > 0.82);
      }
      for (let i = 0; i < 3; i++) {
        const ox = (hash2(prop.x, prop.y, 110 + i) - 0.5) * 30;
        const oy = (hash2(prop.x, prop.y, 120 + i) - 0.5) * 14 + 3;
        ctx.fillStyle = i % 2 ? "#b58b4b" : "#caa35d";
        ctx.fillRect(Math.round(prop.x + ox), Math.round(prop.y + oy), 1, 1);
      }
    }

    // Kitchen garden: dark soil, neat rows, leafy cabbages.
    const gx = 5.15 * TILE;
    const gy = 15.95 * TILE;
    const gw = 4.1 * TILE;
    const gh = 4.2 * TILE;
    ctx.fillStyle = "#8a6a43";
    ctx.fillRect(gx, gy, gw, gh);
    for (let y = gy + 4; y < gy + gh - 2; y += 10) {
      ctx.fillStyle = "#6d5235";
      ctx.fillRect(gx + 3, Math.round(y), gw - 6, 2);
      for (let x = gx + 7; x < gx + gw - 4; x += 11) {
        ctx.fillStyle = "#4e8f48";
        ctx.fillRect(Math.round(x) - 2, Math.round(y) - 4, 5, 4);
        ctx.fillStyle = "#6ab45c";
        ctx.fillRect(Math.round(x) - 1, Math.round(y) - 5, 3, 3);
        ctx.fillStyle = "#84c96e";
        ctx.fillRect(Math.round(x), Math.round(y) - 4, 1, 1);
      }
    }
    ctx.strokeStyle = "rgba(80, 52, 31, 0.32)";
    ctx.lineWidth = 1;
    ctx.strokeRect(gx + 0.5, gy + 0.5, gw - 1, gh - 1);

    // A ring of worn cobbles around the well.
    for (let i = 0; i < 26; i++) {
      const angle = (i / 26) * Math.PI * 2;
      const radius = 28 + (hash2(i, 1, 131) - 0.5) * 6;
      const x = 24 * TILE + Math.cos(angle) * radius;
      const y = 21.7 * TILE + Math.sin(angle) * radius * 0.62;
      ctx.fillStyle = i % 3 === 0 ? "#a8987a" : "#94866b";
      ctx.fillRect(Math.round(x), Math.round(y), 3, 2);
      ctx.fillStyle = "#c0b08c";
      ctx.fillRect(Math.round(x), Math.round(y), 2, 1);
    }

    // Soft dappled light to break up the grass.
    ctx.globalAlpha = 0.045;
    for (let i = 0; i < 34; i++) {
      const x = rng() * WORLD_W;
      const y = rng() * WORLD_H;
      const r = 14 + rng() * 28;
      ctx.fillStyle = "#ffe29b";
      ctx.beginPath();
      ctx.ellipse(x, y, r, r * 0.55, rng() * Math.PI, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    return canvas;
  }

  /* ---------------------------------------------------------------- */
  /* Collision and queries                                             */
  /* ---------------------------------------------------------------- */

  collides(x, y, radius) {
    if (x < radius + 4 || y < radius + 4 || x > WORLD_W - radius - 4 || y > WORLD_H - radius - 4) return true;

    for (const circle of this.solidCircles) {
      const dx = x - circle.x;
      const dy = y - circle.y;
      const min = radius + circle.r;
      if (dx * dx + dy * dy < min * min) return true;
    }
    for (const rect of this.solidRects) {
      const closestX = clamp(x, rect.x, rect.x + rect.w);
      const closestY = clamp(y, rect.y, rect.y + rect.h);
      const dx = x - closestX;
      const dy = y - closestY;
      if (dx * dx + dy * dy < radius * radius) return true;
    }
    return false;
  }
}

/** Keyboard and virtual-joystick input, combined into one movement vector. */
import { clamp } from "./util.js";

const MOVEMENT_KEYS = new Set([
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "KeyW",
  "KeyA",
  "KeyS",
  "KeyD",
]);

export class Input {
  constructor(joystickEl) {
    this.joystickEl = joystickEl;
    this.keys = new Set();
    this.joy = { x: 0, y: 0 };
    this.joyRadius = 40;
    this.pointerId = null;
    this.center = { x: 0, y: 0 };
    this.firstMove = false;
    this.onFirstMove = null;

    this.bindKeyboard();
    this.bindJoystick();
  }

  bindKeyboard() {
    window.addEventListener("keydown", (event) => {
      if (!MOVEMENT_KEYS.has(event.code)) return;
      event.preventDefault();
      this.keys.add(event.code);
      this.signalMove();
    });
    window.addEventListener("keyup", (event) => {
      if (!MOVEMENT_KEYS.has(event.code)) return;
      event.preventDefault();
      this.keys.delete(event.code);
    });
    window.addEventListener("blur", () => this.keys.clear());
  }

  bindJoystick() {
    const el = this.joystickEl;
    if (!el) return;

    const updateCenter = () => {
      const rect = el.getBoundingClientRect();
      this.center.x = rect.left + rect.width / 2;
      this.center.y = rect.top + rect.height / 2;
      this.joyRadius = Math.max(28, rect.width * 0.29);
    };

    const setKnob = (dx, dy) => {
      el.style.setProperty("--joy-x", `${dx.toFixed(1)}px`);
      el.style.setProperty("--joy-y", `${dy.toFixed(1)}px`);
    };

    const release = (event) => {
      if (this.pointerId === null || (event && event.pointerId !== this.pointerId)) return;
      this.pointerId = null;
      this.joy.x = 0;
      this.joy.y = 0;
      setKnob(0, 0);
      el.classList.remove("is-active");
    };

    const move = (event) => {
      if (event.pointerId !== this.pointerId) return;
      const dx = event.clientX - this.center.x;
      const dy = event.clientY - this.center.y;
      const distance = Math.hypot(dx, dy);
      const limit = this.joyRadius;
      const scale = distance > limit ? limit / distance : 1;
      const kx = dx * scale;
      const ky = dy * scale;
      setKnob(kx, ky);

      const magnitude = clamp(distance / limit, 0, 1);
      if (magnitude < 0.16) {
        this.joy.x = 0;
        this.joy.y = 0;
      } else {
        const response = (magnitude - 0.16) / 0.84;
        this.joy.x = (dx / (distance || 1)) * response;
        this.joy.y = (dy / (distance || 1)) * response;
        this.signalMove();
      }
    };

    el.addEventListener("pointerdown", (event) => {
      if (this.pointerId !== null) return;
      event.preventDefault();
      this.pointerId = event.pointerId;
      updateCenter();
      el.classList.add("is-active");
      el.setPointerCapture?.(event.pointerId);
      move(event);
    });
    el.addEventListener("pointermove", (event) => {
      if (this.pointerId === null) return;
      event.preventDefault();
      move(event);
    });
    el.addEventListener("pointerup", release);
    el.addEventListener("pointercancel", release);
    el.addEventListener("lostpointercapture", release);
    window.addEventListener("resize", () => {
      if (this.pointerId !== null) updateCenter();
    });
  }

  signalMove() {
    if (this.firstMove) return;
    this.firstMove = true;
    this.onFirstMove?.();
  }

  get vector() {
    let x = this.joy.x;
    let y = this.joy.y;

    if (this.keys.has("ArrowLeft") || this.keys.has("KeyA")) x -= 1;
    if (this.keys.has("ArrowRight") || this.keys.has("KeyD")) x += 1;
    if (this.keys.has("ArrowUp") || this.keys.has("KeyW")) y -= 1;
    if (this.keys.has("ArrowDown") || this.keys.has("KeyS")) y += 1;

    const length = Math.hypot(x, y);
    if (length > 1) {
      x /= length;
      y /= length;
    }
    return { x, y };
  }
}

/** The hero's smooth, collision-aware movement and walk cycle. */
import { PLAYER } from "./config.js";
import { damp } from "./util.js";

export class Player {
  constructor(world) {
    this.world = world;
    this.x = world.spawn.x;
    this.y = world.spawn.y;
    this.vx = 0;
    this.vy = 0;
    this.radius = PLAYER.radius;
    this.facing = "down";
    this.animDistance = 0;
    this.movingDistance = 0;
    this.idleTime = 0;
    this.moving = false;
    this.speed = 0;
    this.stepPulse = 0;
  }

  update(dt, vector) {
    const speed = PLAYER.walkSpeed;
    const targetX = vector.x * speed;
    const targetY = vector.y * speed;
    const responsiveness = 1 - Math.exp(-PLAYER.acceleration * dt);

    this.vx += (targetX - this.vx) * responsiveness;
    this.vy += (targetY - this.vy) * responsiveness;

    if (!vector.x && !vector.y && Math.hypot(this.vx, this.vy) < 1.2) {
      this.vx = 0;
      this.vy = 0;
    }

    const oldX = this.x;
    const oldY = this.y;

    const nextX = this.x + this.vx * dt;
    if (!this.world.collides(nextX, this.y, this.radius)) {
      this.x = nextX;
    } else {
      this.vx = 0;
    }

    const nextY = this.y + this.vy * dt;
    if (!this.world.collides(this.x, nextY, this.radius)) {
      this.y = nextY;
    } else {
      this.vy = 0;
    }

    const moved = Math.hypot(this.x - oldX, this.y - oldY);
    this.speed = moved / Math.max(dt, 0.0001);
    this.moving = moved > 0.05;
    this.movingDistance += moved;
    this.animDistance += moved;

    if (this.moving) {
      this.idleTime = 0;
      const absX = Math.abs(this.vx);
      const absY = Math.abs(this.vy);
      if (absX > absY * 1.12) this.facing = this.vx >= 0 ? "right" : "left";
      else if (absY > 0.8) this.facing = this.vy >= 0 ? "down" : "up";
    } else {
      this.idleTime += dt;
    }

    this.stepPulse += moved;
  }

  get frameIndex() {
    if (!this.moving) return 0;
    return Math.floor(this.animDistance / PLAYER.animDistance) % 4;
  }

  get breathingOffset() {
    if (this.moving) return 0;
    return Math.sin(this.idleTime * 2.2) > 0.55 ? -1 : 0;
  }

  lookAhead() {
    const speed = Math.hypot(this.vx, this.vy) || 1;
    return {
      x: (this.vx / speed) * Math.min(1, speed / PLAYER.walkSpeed) * 9,
      y: (this.vy / speed) * Math.min(1, speed / PLAYER.walkSpeed) * 9,
    };
  }
}

/** A smoothed camera that follows the hero and respects the world bounds. */
import { WORLD_W, WORLD_H, CAMERA } from "./config.js";
import { clamp, damp } from "./util.js";

export class Camera {
  constructor(world) {
    this.world = world;
    this.x = 0;
    this.y = 0;
    this.viewW = 320;
    this.viewH = 200;
    this.initialized = false;
  }

  resize(viewW, viewH) {
    this.viewW = viewW;
    this.viewH = viewH;
    if (!this.initialized) this.snap(this.world.spawn.x, this.world.spawn.y - 8);
    else this.clampToWorld();
  }

  snap(targetX, targetY) {
    this.x = targetX - this.viewW / 2;
    this.y = targetY - this.viewH / 2;
    this.initialized = true;
    this.clampToWorld();
  }

  clampToWorld() {
    if (this.viewW >= WORLD_W) this.x = (WORLD_W - this.viewW) / 2;
    else this.x = clamp(this.x, 0, WORLD_W - this.viewW);

    if (this.viewH >= WORLD_H) this.y = (WORLD_H - this.viewH) / 2;
    else this.y = clamp(this.y, 0, WORLD_H - this.viewH);
  }

  update(dt, player) {
    const look = player.lookAhead();
    const targetX = player.x + look.x - this.viewW / 2;
    const targetY = player.y + look.y - 8 - this.viewH / 2;
    this.x = damp(this.x, targetX, CAMERA.follow, dt);
    this.y = damp(this.y, targetY, CAMERA.follow, dt);
    this.clampToWorld();
  }
}

/** Drifting pollen, chimney smoke, butterflies, and footstep dust. */
import { WORLD_W, WORLD_H, TILE } from "./config.js";
import { mulberry32, TAU } from "./util.js";

export class Ambient {
  constructor(world) {
    this.world = world;
    this.rng = mulberry32(8080);
    this.time = 0;
    this.smokeTimer = 0;
    this.smoke = [];
    this.dust = [];
    this.pollen = [];
    this.leaves = [];
    this.butterflies = [];
    this.sparkles = [];

    for (let i = 0; i < 64; i++) {
      this.pollen.push({
        x: this.rng() * WORLD_W,
        y: this.rng() * WORLD_H,
        phase: this.rng() * TAU,
        speed: 1.5 + this.rng() * 3.5,
        drift: 2.5 + this.rng() * 4.5,
        size: this.rng() > 0.8 ? 2 : 1,
        alpha: 0.24 + this.rng() * 0.42,
      });
    }

    for (let i = 0; i < 14; i++) {
      this.leaves.push({
        x: this.rng() * WORLD_W,
        y: this.rng() * WORLD_H,
        phase: this.rng() * TAU,
        speed: 3 + this.rng() * 4,
        color: this.rng() > 0.5 ? "#c18b4f" : "#8caf55",
      });
    }

    const butterflyHomes = [
      [16.5, 18.5],
      [10.4, 16.8],
      [26.4, 25.2],
      [34.2, 27.6],
      [30.5, 14.2],
      [20.6, 29.4],
      [7.2, 22.8],
    ];
    for (const [tx, ty] of butterflyHomes) {
      this.butterflies.push({
        homeX: tx * TILE,
        homeY: ty * TILE,
        phase: this.rng() * TAU,
        speed: 0.5 + this.rng() * 0.5,
        radius: 11 + this.rng() * 14,
        wing: this.rng() > 0.45 ? "#ecc567" : "#e6a7bc",
      });
    }

    // A little constellation of magic around the tower window.
    for (let i = 0; i < 7; i++) {
      this.sparkles.push({
        x: 40 * TILE + (this.rng() - 0.5) * 34,
        y: 9.6 * TILE + (this.rng() - 0.5) * 34,
        phase: this.rng() * TAU,
        speed: 0.5 + this.rng() * 0.8,
      });
    }
  }

  update(dt, player) {
    this.time += dt;
    const t = this.time;

    for (const p of this.pollen) {
      p.x += (p.drift + Math.sin(t * 0.6 + p.phase) * 2.4) * dt;
      p.y += (-p.speed + Math.cos(t * 0.9 + p.phase) * 1.8) * dt;
      if (p.x > WORLD_W + 8) p.x = -8;
      if (p.x < -8) p.x = WORLD_W + 8;
      if (p.y < -8) p.y = WORLD_H + 8;
      if (p.y > WORLD_H + 8) p.y = -8;
    }

    for (const leaf of this.leaves) {
      leaf.x += (leaf.speed + Math.sin(t * 1.2 + leaf.phase) * 6) * dt;
      leaf.y += (2.2 + Math.cos(t * 1.5 + leaf.phase) * 3) * dt;
      if (leaf.x > WORLD_W + 10) leaf.x = -10;
      if (leaf.y > WORLD_H + 10) {
        leaf.y = -10;
        leaf.x = this.rng() * WORLD_W;
      }
    }

    this.smokeTimer -= dt;
    if (this.smokeTimer <= 0) {
      this.smokeTimer = 0.44;
      for (const source of this.world.smokeSources) {
        if (this.smoke.length > 30) break;
        this.smoke.push({
          x: source.x + (this.rng() - 0.5) * 3,
          y: source.y,
          vx: 1.6 + this.rng() * 2.2,
          vy: -8 - this.rng() * 5,
          life: 0,
          maxLife: 2.8 + this.rng() * 2.2,
          size: 2 + Math.floor(this.rng() * 2),
          phase: this.rng() * TAU,
        });
      }
    }

    for (let i = this.smoke.length - 1; i >= 0; i--) {
      const s = this.smoke[i];
      s.life += dt;
      s.x += (s.vx + Math.sin(t * 1.3 + s.phase) * 1.1) * dt;
      s.y += s.vy * dt;
      s.vy *= 1 - 0.12 * dt;
      if (s.life > s.maxLife) this.smoke.splice(i, 1);
    }

    for (let i = this.dust.length - 1; i >= 0; i--) {
      const d = this.dust[i];
      d.life += dt;
      d.x += d.vx * dt;
      d.y += d.vy * dt;
      d.vy *= 1 - 1.8 * dt;
      if (d.life > d.maxLife) this.dust.splice(i, 1);
    }
  }

  footstep(x, y, facing) {
    if (this.dust.length > 18) return;
    const side = facing === "left" ? -1 : facing === "right" ? 1 : 0;
    const back = facing === "up" ? 1 : facing === "down" ? -1 : 0;
    for (let i = 0; i < 2; i++) {
      this.dust.push({
        x: x + side * 3 + (this.rng() - 0.5) * 4,
        y: y - 1 + back * 2,
        vx: (this.rng() - 0.5) * 7 + side * 3,
        vy: -3 - this.rng() * 3,
        life: 0,
        maxLife: 0.32 + this.rng() * 0.18,
      });
    }
  }

  visible(x, y, view, margin = 36) {
    return x > view.x - margin && x < view.x + view.w + margin && y > view.y - margin && y < view.y + view.h + margin;
  }

  draw(ctx, view) {
    const t = this.time;

    // Pollen motes and falling leaves, light over the whole scene.
    for (const p of this.pollen) {
      if (!this.visible(p.x, p.y, view, 10)) continue;
      const alpha = p.alpha * (0.7 + Math.sin(t * 2.1 + p.phase) * 0.3);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = "#ffe7a2";
      ctx.fillRect(Math.round(p.x), Math.round(p.y), p.size, p.size);
    }
    ctx.globalAlpha = 1;

    for (const leaf of this.leaves) {
      if (!this.visible(leaf.x, leaf.y, view, 10)) continue;
      ctx.fillStyle = leaf.color;
      ctx.globalAlpha = 0.68;
      ctx.fillRect(Math.round(leaf.x), Math.round(leaf.y), 2, 1);
      ctx.globalAlpha = 1;
    }

    // Butterflies loop around their flower patches.
    for (const b of this.butterflies) {
      const wobble = Math.sin(t * b.speed * 2.2 + b.phase);
      const x = b.homeX + Math.cos(t * b.speed + b.phase) * b.radius;
      const y = b.homeY + Math.sin(t * b.speed * 1.3 + b.phase) * b.radius * 0.58 + wobble * 2;
      if (!this.visible(x, y, view, 16)) continue;
      const flap = Math.sin(t * 10 + b.phase) > 0;
      ctx.fillStyle = b.wing;
      if (flap) {
        ctx.fillRect(Math.round(x) - 2, Math.round(y) - 1, 2, 2);
        ctx.fillRect(Math.round(x) + 1, Math.round(y) - 1, 2, 2);
        ctx.fillStyle = "#f7e4ad";
        ctx.fillRect(Math.round(x) - 2, Math.round(y) - 1, 1, 1);
        ctx.fillRect(Math.round(x) + 2, Math.round(y) - 1, 1, 1);
      } else {
        ctx.fillRect(Math.round(x) - 1, Math.round(y) - 2, 2, 3);
        ctx.fillRect(Math.round(x) + 1, Math.round(y) - 1, 1, 2);
      }
      ctx.fillStyle = "#4a3b31";
      ctx.fillRect(Math.round(x), Math.round(y) - 1, 1, 2);
    }

    // Tower magic: a handful of twinkling gold pixels.
    for (const s of this.sparkles) {
      if (!this.visible(s.x, s.y, view, 18)) continue;
      const twinkle = Math.sin(t * 2.2 * s.speed + s.phase);
      if (twinkle < 0.25) continue;
      ctx.globalAlpha = 0.32 + twinkle * 0.5;
      ctx.fillStyle = "#ffe6a2";
      const size = twinkle > 0.82 ? 2 : 1;
      ctx.fillRect(Math.round(s.x), Math.round(s.y), size, size);
      if (twinkle > 0.9) {
        ctx.fillRect(Math.round(s.x) - 1, Math.round(s.y), 1, 1);
        ctx.fillRect(Math.round(s.x) + 1, Math.round(s.y), 1, 1);
        ctx.fillRect(Math.round(s.x), Math.round(s.y) - 1, 1, 1);
        ctx.fillRect(Math.round(s.x), Math.round(s.y) + 1, 1, 1);
      }
    }
    ctx.globalAlpha = 1;

    // Chimney smoke.
    for (const s of this.smoke) {
      if (!this.visible(s.x, s.y, view, 12)) continue;
      const life = s.life / s.maxLife;
      const alpha = Math.sin(Math.min(1, life * 2.5) * Math.PI * 0.5) * (1 - life) * 0.4;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = "#ddd9c6";
      ctx.fillRect(Math.round(s.x), Math.round(s.y), s.size, s.size);
      if (s.size > 2) ctx.fillRect(Math.round(s.x) + 1, Math.round(s.y) - 1, 1, 1);
    }
    ctx.globalAlpha = 1;

    // Footstep dust, low and quick.
    for (const d of this.dust) {
      if (!this.visible(d.x, d.y, view, 8)) continue;
      const life = d.life / d.maxLife;
      ctx.globalAlpha = (1 - life) * 0.42;
      ctx.fillStyle = "#d8c18c";
      ctx.fillRect(Math.round(d.x), Math.round(d.y), 1, 1);
    }
    ctx.globalAlpha = 1;
  }
}

/** Pixel-perfect canvas renderer. */
import { WORLD_W, WORLD_H } from "./config.js";
import { makeHeroSprites } from "./art.js";

export class Renderer {
  constructor(canvas, world) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d", { alpha: false });
    this.world = world;
    this.hero = makeHeroSprites();
    this.dpr = 1;
    this.zoom = 3;
    this.viewW = 320;
    this.viewH = 200;
    this.drawables = [];
    this.resize();
  }

  resize() {
    const width = Math.max(1, window.innerWidth);
    const height = Math.max(1, window.innerHeight);
    const base = width >= 1100 && height >= 560 ? 4 : 3;
    const zoom = Math.max(
      base,
      Math.ceil(width / WORLD_W),
      Math.ceil(height / WORLD_H)
    );

    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.zoom = zoom;
    this.viewW = width / zoom;
    this.viewH = height / zoom;

    this.canvas.width = Math.round(width * this.dpr);
    this.canvas.height = Math.round(height * this.dpr);
    this.canvas.style.width = `${width}px`;
    this.canvas.style.height = `${height}px`;

    const ctx = this.ctx;
    ctx.imageSmoothingEnabled = false;
    ctx.lineWidth = 1;
  }

  render(camera, player, ambient, time) {
    const ctx = this.ctx;
    const { dpr, zoom } = this;
    const camX = Math.round(camera.x);
    const camY = Math.round(camera.y);
    const viewW = this.viewW;
    const viewH = this.viewH;

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = "#274b36";
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    ctx.setTransform(dpr * zoom, 0, 0, dpr * zoom, -camX * dpr * zoom, -camY * dpr * zoom);
    ctx.imageSmoothingEnabled = false;

    // Baked ground.
    ctx.drawImage(this.world.ground, camX, camY, viewW, viewH, camX, camY, viewW, viewH);

    this.drawWater(ctx, time, camX, camY, viewW, viewH);

    // Cull and depth-sort everything that stands on the ground.
    const list = this.drawables;
    list.length = 0;
    for (const prop of this.world.props) {
      const sprite = prop.sprite;
      const left = prop.x - sprite.ax;
      const top = prop.y - sprite.ay;
      if (
        left + sprite.canvas.width < camX - 8 ||
        left > camX + viewW + 8 ||
        top + sprite.canvas.height < camY - 12 ||
        top > camY + viewH + 12
      ) {
        continue;
      }
      list.push(prop);
    }
    list.push({ kind: "player", sortY: player.y, player });
    list.sort((a, b) => a.sortY - b.sortY);

    for (const item of list) {
      if (item.kind === "player") this.drawPlayer(ctx, item.player);
      else {
        const sprite = item.sprite;
        ctx.drawImage(sprite.canvas, Math.round(item.x - sprite.ax), Math.round(item.y - sprite.ay));
      }
    }

    this.drawLandmarkBeacons(ctx, time, camX, camY, viewW, viewH);
    ambient.draw(ctx, { x: camX, y: camY, w: viewW, h: viewH });

    ctx.setTransform(1, 0, 0, 1, 0, 0);
  }

  drawPlayer(ctx, player) {
    const frame = player.facing;
    const sprite = this.hero.frames[frame][player.frameIndex];
    const x = Math.round(player.x);
    const y = Math.round(player.y + player.breathingOffset);

    // Ground shadow in two soft, pixel-ish passes.
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = "#122f22";
    ctx.beginPath();
    ctx.ellipse(player.x, player.y + 1, 8, 3.2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.15;
    ctx.beginPath();
    ctx.ellipse(player.x - 1, player.y, 5, 2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;

    ctx.drawImage(sprite, x - this.hero.ax, y - this.hero.ay);
  }

  drawWater(ctx, time, camX, camY, viewW, viewH) {
    const minX = Math.floor(camX / 16) - 1;
    const maxX = Math.ceil((camX + viewW) / 16) + 1;
    const minY = Math.floor(camY / 16) - 1;
    const maxY = Math.ceil((camY + viewH) / 16) + 1;
    ctx.globalAlpha = 0.45;
    ctx.fillStyle = "#a6d8d2";
    for (const tile of this.world.waterTiles) {
      if (tile.x < minX || tile.x > maxX || tile.y < minY || tile.y > maxY) continue;
      const phase = time * 1.7 + tile.x * 0.9 + tile.y * 1.4;
      const wave = Math.sin(phase);
      if (wave < 0.1) continue;
      const x = tile.x * 16 + 3 + Math.floor((wave * 0.5 + 0.5) * 8);
      const y = tile.y * 16 + 5 + (tile.y % 2) * 5;
      ctx.fillRect(x, y, 3 + (tile.x % 2), 1);
      if (wave > 0.72) ctx.fillRect(x + 5, y + 3, 2, 1);
    }
    ctx.globalAlpha = 1;
  }

  drawLandmarkBeacons(ctx, time, camX, camY, viewW, viewH) {
    for (const landmark of this.world.landmarks) {
      if (landmark.found) continue;
      if (
        landmark.x < camX - 20 ||
        landmark.x > camX + viewW + 20 ||
        landmark.y < camY - 20 ||
        landmark.y > camY + viewH + 20
      ) {
        continue;
      }
      const pulse = 0.5 + Math.sin(time * 2.2 + landmark.x * 0.01) * 0.5;
      const x = Math.round(landmark.x);
      const y = Math.round(landmark.y - 34 - pulse * 2);
      ctx.globalAlpha = 0.22 + pulse * 0.38;
      ctx.fillStyle = "#ffe39a";
      ctx.fillRect(x, y, 1, 1);
      if (pulse > 0.42) {
        ctx.fillRect(x - 1, y - 1, 1, 1);
        ctx.fillRect(x + 1, y - 1, 1, 1);
        ctx.fillRect(x - 1, y + 1, 1, 1);
        ctx.fillRect(x + 1, y + 1, 1, 1);
      }
      ctx.globalAlpha = 1;
    }
  }
}

/** Game orchestration: world, loop, discoveries, and UI. */
import { World } from "./world.js";
import { Renderer } from "./renderer.js";
import { Camera } from "./camera.js";
import { Player } from "./player.js";
import { Ambient } from "./ambient.js";
import { Input } from "./input.js";

export class Game {
  constructor() {
    this.canvas = document.getElementById("game-canvas");
    this.joystick = document.getElementById("joystick");
    this.hint = document.querySelector(".hint");
    this.toast = document.getElementById("toast");
    this.toastTitle = document.getElementById("toast-title");
    this.toastKicker = this.toast.querySelector(".toast-kicker");
    this.foundCount = document.getElementById("found-count");
    this.foundCard = document.querySelector(".found-card");

    this.world = new World();
    this.renderer = new Renderer(this.canvas, this.world);
    this.camera = new Camera(this.world);
    this.player = new Player(this.world);
    this.ambient = new Ambient(this.world);
    this.input = new Input(this.joystick);

    this.camera.resize(this.renderer.viewW, this.renderer.viewH);
    this.camera.snap(this.player.x, this.player.y - 8);

    this.time = 0;
    this.lastTimestamp = 0;
    this.running = false;
    this.toastTimer = 0;
    this.lastStepPulse = 0;
    this.stepAccumulator = 0;
    this.completeShown = false;

    this.input.onFirstMove = () => {
      window.setTimeout(() => this.hint?.classList.add("is-hidden"), 1300);
    };

    this.onResize = this.onResize.bind(this);
    this.frame = this.frame.bind(this);
    window.addEventListener("resize", this.onResize, { passive: true });
    window.visualViewport?.addEventListener("resize", this.onResize, { passive: true });
    document.addEventListener("visibilitychange", () => {
      this.lastTimestamp = 0;
    });

    this.updateHud();
    this.running = true;
    requestAnimationFrame(this.frame);
  }

  onResize() {
    this.renderer.resize();
    this.camera.resize(this.renderer.viewW, this.renderer.viewH);
  }

  frame(now) {
    if (!this.running) return;
    if (!this.lastTimestamp) this.lastTimestamp = now;
    const dt = Math.min(0.05, Math.max(0, (now - this.lastTimestamp) / 1000));
    this.lastTimestamp = now;
    this.update(dt);
    this.renderer.render(this.camera, this.player, this.ambient, this.time);
    requestAnimationFrame(this.frame);
  }

  update(dt) {
    this.time += dt;
    const vector = this.input.vector;
    this.player.update(dt, vector);
    this.ambient.update(dt, this.player);
    this.camera.update(dt, this.player);

    // Kick up a little dust in time with the walk cycle.
    const pulse = this.player.stepPulse - this.lastStepPulse;
    this.lastStepPulse = this.player.stepPulse;
    if (this.player.moving) this.stepAccumulator += pulse;
    if (this.stepAccumulator > 13) {
      this.stepAccumulator = 0;
      this.ambient.footstep(this.player.x, this.player.y, this.player.facing);
    }

    this.checkLandmarks();
  }

  checkLandmarks() {
    for (const landmark of this.world.landmarks) {
      if (landmark.found) continue;
      const dx = this.player.x - landmark.x;
      const dy = this.player.y - landmark.y;
      if (dx * dx + dy * dy <= landmark.radius * landmark.radius) {
        landmark.found = true;
        this.updateHud();
        this.showToast("Landmark discovered", landmark.title);
        if (this.world.landmarks.every((item) => item.found) && !this.completeShown) {
          this.completeShown = true;
          this.foundCard?.classList.add("is-complete");
          window.setTimeout(() => {
            this.showToast("Every landmark found", "The vale is yours to wander", 4600);
          }, 3800);
        }
        break;
      }
    }
  }

  updateHud() {
    const found = this.world.landmarks.filter((landmark) => landmark.found).length;
    if (this.foundCount) this.foundCount.textContent = String(found);
    this.foundCard?.classList.toggle("is-complete", found === this.world.landmarks.length);
  }

  showToast(kicker, title, duration = 3400) {
    if (!this.toast) return;
    this.toastKicker.textContent = kicker;
    this.toastTitle.textContent = title;
    this.toast.classList.add("is-visible");
    window.clearTimeout(this.toastTimer);
    this.toastTimer = window.setTimeout(() => {
      this.toast.classList.remove("is-visible");
    }, duration);
  }
}

import { Game } from "./game.js";

function boot() {
  try {
    const game = new Game();
    // Handy for tinkering in the console; the game is intentionally easy to extend.
    window.mosswold = game;
  } catch (error) {
    console.error(error);
    const message = document.createElement("div");
    message.className = "noscript";
    message.textContent = "The vale could not wake. Please reload the page.";
    document.getElementById("app")?.appendChild(message);
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot, { once: true });
} else {
  boot();
}

