import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true })
const errors = []
page.on('pageerror', e => errors.push(e.message))
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.waitForTimeout(700)
const initial = await page.evaluate(() => {
  const g = window.mosswold
  return {
    boot: Math.round(window.__bootMs),
    player: { x: g.player.x, y: g.player.y },
    zoom: g.renderer.zoom,
    view: [g.renderer.viewW, g.renderer.viewH],
    intro: getComputedStyle(document.getElementById('intro')).opacity,
    canvas: [g.canvas.width, g.canvas.height],
    found: g.world.landmarks.filter(l => l.found).length,
  }
})
console.log('initial', initial)

const box = await page.locator('#joystick').boundingBox()
const cx = box.x + box.width / 2
const cy = box.y + box.height / 2
await page.mouse.move(cx, cy)
await page.mouse.down()
await page.mouse.move(cx, cy - 34, { steps: 4 })
await page.waitForTimeout(700)
const duringDrag = await page.evaluate(() => ({ x: window.mosswold.player.x, y: window.mosswold.player.y, facing: window.mosswold.player.facing }))
await page.mouse.up()
await page.waitForTimeout(300)
const afterDrag = await page.evaluate(() => ({ x: window.mosswold.player.x, y: window.mosswold.player.y, intro: getComputedStyle(document.getElementById('intro')).opacity, hint: getComputedStyle(document.querySelector('.hint')).opacity }))
console.log('joystick', duringDrag, afterDrag)

await page.keyboard.down('ArrowRight')
await page.waitForTimeout(500)
await page.keyboard.up('ArrowRight')
const afterKeys = await page.evaluate(() => ({ x: window.mosswold.player.x, y: window.mosswold.player.y, facing: window.mosswold.player.facing }))
console.log('keyboard', afterKeys)

// Visit each landmark by jumping the player there; the real game is walking,
// but this verifies the discovery pipeline and HUD.
for (const id of ['well', 'cottage', 'inn', 'tower']) {
  await page.evaluate((id) => {
    const g = window.mosswold
    const l = g.world.landmarks.find(v => v.id === id)
    g.player.x = l.x
    g.player.y = l.y
  }, id)
  await page.waitForTimeout(120)
}
const foundState = await page.evaluate(() => ({
  found: window.mosswold.world.landmarks.filter(l => l.found).map(l => l.id),
  hud: document.getElementById('found-count').textContent,
  toast: document.getElementById('toast').className,
  toastTitle: document.getElementById('toast-title').textContent,
}))
console.log('landmarks', foundState)

const fps = await page.evaluate(() => new Promise(resolve => {
  let frames = 0
  const start = performance.now()
  function tick(now) {
    frames++
    if (now - start >= 1000) resolve(Math.round((frames * 1000) / (now - start)))
    else requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
}))
console.log('fps', fps)
await page.screenshot({ path: 'screenshots/test-mobile.png' })
console.log('errors', errors)
await browser.close()

